# apply_prerace_fix.py — makes the scraper preserve pre-race entry lists
# (finishing_position=0 for everyone until race day).
import base64, pathlib

FILES = {
    'src/scrape/nascar_com.py': '',
    'src/features/build_features.py': '',
    'src/cli/predict_next.py': '',
}


def main():
    for target, b64 in FILES.items():
        p = pathlib.Path(target)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64))
        print(f"wrote {target}")
    print("\nNow run:  python -m src.cli.predict_next")

if __name__ == "__main__":
    main()
